package com.example.orders.dto;import javax.validation.constraints.*;import java.math.BigDecimal;public class OrderRequest{@NotBlank private String name;@NotBlank private String customerId;@NotBlank private String productType;@NotNull @Min(1) private Integer quantity;@NotNull @DecimalMin("0.01") private BigDecimal price;public String getName(){return name;}public void setName(String v){name=v;}public String getCustomerId(){return customerId;}public void setCustomerId(String v){customerId=v;}public String getProductType(){return productType;}public void setProductType(String v){productType=v;}public Integer getQuantity(){return quantity;}public void setQuantity(Integer v){quantity=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}}